216	void FVirtualTexturePhysicalSpace::UpdateResidencyTracking(uint32 Frame)
217	{
218		float LockedUpperBound = CVarVTResidencyLockedUpperBound.GetValueOnRenderThread();
219		float LowerBound = CVarVTResidencyLowerBound.GetValueOnRenderThread();
220		float UpperBound = CVarVTResidencyUpperBound.GetValueOnRenderThread();
221		float AdjustmentRate = CVarVTResidencyAdjustmentRate.GetValueOnRenderThread();
222		float MaxMipMapBias = CVarVTResidencyMaxMipMapBias.GetValueOnRenderThread();
223	
224		const uint32 NumPages = Pool.GetNumPages();
225		const uint32 NumLockedPages = Pool.GetNumLockedPages();
226		const float LockedPageResidency = (float)NumLockedPages / (float)NumPages;
227	
228		const uint32 PageFreeThreshold = FMath::Max(VirtualTextureScalability::GetPageFreeThreshold(), 0u);
229		const uint32 FrameMinusThreshold = Frame > PageFreeThreshold ? Frame - PageFreeThreshold : 0;
230		const uint32 NumVisiblePages = Pool.GetNumVisiblePages(FrameMinusThreshold);
231		// [Haro++] GetNumVisiblePages() no longer counts locked pages, so use the unlocked page count
232		// as the denominator to keep the ratio in [0,1]. Guard against a fully locked pool: FreeHeap is
233		// empty then and a divide would produce NaN, which Clamp() below wouldn't catch. Residency 0 is
234		// correct there anyway - the bias can't influence locked pages, and the LockedUpperBound
235		// kill-switch zeroes the bias for such pools.
236		const uint32 NumUnlockedPages = Pool.GetNumUnlockedPages();
237		const float VisiblePageResidency = NumUnlockedPages > 0u ? (float)NumVisiblePages / (float)NumUnlockedPages : 0.0f;
238		// [Haro--]
239		
240		if (ResidencyMipMapBias > 0.f && VisiblePageResidency < LowerBound)
241		{
242			ResidencyMipMapBias -= AdjustmentRate * (LowerBound - VisiblePageResidency);
243		}
244		else if (VisiblePageResidency > UpperBound)
245		{
246			ResidencyMipMapBias += AdjustmentRate * (VisiblePageResidency - UpperBound);
247		}
248	
249		if (ResidencyMipMapBias > 0.f)
250		{
251			LastFrameOversubscribed = Frame;
252		}
253	
254		ResidencyMipMapBias = FMath::Clamp(ResidencyMipMapBias, 0.f, MaxMipMapBias);
255	
256		if (CVarVTResidencyEnableMipMapBias.GetValueOnRenderThread() == 0 ||
257			!DescriptionExt.bEnableResidencyMipMapBias ||
258			LockedPageResidency > LockedUpperBound)
259		{
260			ResidencyMipMapBias = 0.f;
261		}
262	
263	#if !UE_BUILD_SHIPPING
264		LockedHistory[HistoryIndex+1] = LockedPageResidency;
265		VisibleHistory[HistoryIndex+1] = VisiblePageResidency;
266		MipMapBiasHistory[HistoryIndex+1] = ResidencyMipMapBias / MaxMipMapBias;
267		HistoryIndex++;
268	#endif
