249	/** Calculate mip level. Also stores derivatives to OutResult for use when sampling physical texture. */
250	int TextureComputeVirtualMipLevel(
251		in out VTPageTableResult OutResult,
252		float2 dUVdx, float2 dUVdy, float MipBias,
253		float2 SvPositionXY,
254		VTPageTableUniform PageTableUniform,
255		bool bUseStochasticMipNoise = true,
256		bool bUseMipBias = true,
257		int MipBiasCutoffVLevel = -1)
258	{
259		OutResult.dUVdx = dUVdx * PageTableUniform.SizeInPages;
260		OutResult.dUVdy = dUVdy * PageTableUniform.SizeInPages;
261	
262		// Always compute mip level using MipLevelAniso2D, even if VIRTUAL_TEXTURE_ANISOTROPIC_FILTERING is disabled
263		// This way the VT mip level selection will come much closer to HW mip selection, even if we're not sampling the texture using anisotropic filtering
264		const float ComputedLevel = MipLevelAniso2D(OutResult.dUVdx, OutResult.dUVdy, PageTableUniform.MaxAnisoLog2);
265	
266	#if VIRTUAL_TEXTURE_MANUAL_TRILINEAR_FILTERING
267		const float Noise = 0.f;
268	#elif VIRTUAL_TEXTURE_FORCE_BILINEAR_FILTERING
269		const float Noise = 0.5f;
270	#else
271		const float Noise = bUseStochasticMipNoise ? GetStochasticMipNoise(SvPositionXY) : 0.f;
272	#endif
273	
274		const float MipLevelFromDerivatives = ComputedLevel + Noise + GetGlobalVirtualTextureMipBias();
275		const float MipLevelWithBias = MipLevelFromDerivatives + MipBias;
276		const int VLevelWithBias = (int)floor(MipLevelWithBias) + int(PageTableUniform.vPageTableMipBias);
277		const bool bApplyMipBias = bUseMipBias && (MipBiasCutoffVLevel < 0 || VLevelWithBias < MipBiasCutoffVLevel);
278		const float MipLevel = bApplyMipBias ? MipLevelWithBias : MipLevelFromDerivatives;
279		const float MipLevelFloor = floor(MipLevel);
280		
281		OutResult.MipLevelFrac = MipLevel - MipLevelFloor;
282	
283		return (int)MipLevelFloor + int(PageTableUniform.vPageTableMipBias);
284	}
